import importlib.util
import sys
from pathlib import Path

import numpy as np
import pytest

WT = Path("/Users/connorott/plugins/dev-team-workspace/iteration-b1/rl9-incremental-A3-r1/with_skill/project/.claude/worktrees/agent-a482a9d33d6da1b10")
spec = importlib.util.spec_from_file_location("ti", WT / "tests/intent/rllab/test_interrupt.py")
ti = importlib.util.module_from_spec(spec)
sys.modules["ti"] = ti
spec.loader.exec_module(ti)

from rllab.core import SOLO
from rllab.train import train


class EvalInterrupt(ti._InterruptedAgent):
    def __init__(self):
        super().__init__()
        self.greedy = 0

    def act(self, obs, *, explore):
        if not explore:
            self.greedy += 1
            if self.greedy == 25:
                raise KeyboardInterrupt
        return np.ones((obs.shape[0],), dtype=np.int64)

    def learn(self, t):
        self.learns += 1


class StepEnv(ti._LoopEnv):
    count = 0

    def step(self, actions):
        StepEnv.count += 1
        if StepEnv.count == 60:
            raise KeyboardInterrupt
        return super().step(actions)


def report(root):
    for p in root.rglob("*"):
        print(p.relative_to(root), p.read_text() if p.is_file() and p.suffix in {"", ".csv"} else "")


def test_eval(tmp_path):
    with pytest.raises(KeyboardInterrupt):
        train(ti._LoopEnv, {SOLO: EvalInterrupt()}, ti._settings(), root=tmp_path)
    report(tmp_path)


def test_step(tmp_path):
    with pytest.raises(KeyboardInterrupt):
        train(StepEnv, {SOLO: ti._InterruptedAgent()}, ti._settings(), root=tmp_path)
    report(tmp_path)


def test_ok(tmp_path):
    ag = ti._InterruptedAgent()
    ag.learn = lambda t: None
    train(ti._LoopEnv, {SOLO: ag}, ti._settings(), root=tmp_path)
    report(tmp_path)
